from decimal import Decimal
import json
from pathlib import Path
import sys


def parse_date(val):
    val = val.strip()
    if not val:
        return None
    try:
        num = float(val)
        if num < 100000:
            d = datetime.date(1899, 12, 30) + datetime.timedelta(days=int(round(num)))
            return d.strftime("%Y-%m-%d")
    except ValueError:
        pass

    for fmt in (
        "%Y-%m-%d",
        "%m/%d/%Y",
        "%Y/%m/%d",
        "%d-%b-%Y",
        "%B %d, %Y",
        "%b %d, %Y",
        "%Y%m%d",
    ):
        try:
            return datetime.datetime.strptime(val, fmt).date().strftime("%Y-%m-%d")
        except ValueError:
            pass
    return val


def parse_amount(val):
    val = val.strip().replace("$", "").replace(",", "")
    if not val:
        return None, None
    try:
        d = Decimal(val)
        return d, val
    except Exception:
        return None, val


