            docs_data[doc_name] = by_case
        else:
            docs_data[doc_name] = {}

    pairs = manifest.get("pairs", [])
    facts_by_rule = manifest.get("facts", {})

    output = {}

    for pair in pairs:
        if "::" not in pair:
