import csv
import datetime
from decimal import Decimal
import json
import os
import sys

FACT_CONFIG = {
    "offered wage": ("WAGE_RATE_OF_PAY_FROM", "amount"),
    "offered_wage": ("WAGE_RATE_OF_PAY_FROM", "amount"),
    "prevailing wage": ("PREVAILING_WAGE", "amount"),
    "prevailing_wage": ("PREVAILING_WAGE", "amount"),
    "begin date": ("BEGIN_DATE", "date"),
    "begin_date": ("BEGIN_DATE", "date"),
    "end date": ("END_DATE", "date"),
    "end_date": ("END_DATE", "date"),
}


def parse_date(val):
    val = val.strip()
    if not val:
        return None

    if "-" in val or "/" in val:
        for fmt in (
            "%Y-%m-%d",
            "%m/%d/%Y",
            "%d/%m/%Y",
            "%Y/%m/%d",
            "%m-%d-%Y",
            "%d-%m-%Y",
        ):
            try:
                return (
                    datetime.datetime.strptime(val, fmt)
                    .date()
                    .strftime("%Y-%m-%d")
                )
            except ValueError:
                pass

    if (
        len(val) == 8
        and val.isdigit()
        and (val.startswith("19") or val.startswith("20"))
    ):
        try:
            return (
                datetime.datetime.strptime(val, "%Y%m%d")
                .date()
                .strftime("%Y-%m-%d")
            )
        except ValueError:
            pass

    try:
        num = float(val)
        if 1 <= num <= 100000:
            d = datetime.date(1899, 12, 30) + datetime.timedelta(days=int(num))
            return d.strftime("%Y-%m-%d")
    except ValueError:
        pass

    return val


def format_amount(val):
    val = val.strip().replace("$", "").replace(",", "")
    if not val:
        return None
    try:
        d = Decimal(val)
        if d == d.to_integral():
            return str(d.to_integral())
        return str(d)
    except Exception:
        return val


def format_value(raw_val, val_type):
    if raw_val is None:
        return None
    raw_val = raw_val.strip()
    if not raw_val:
        return None

    if val_type == "date":
        return parse_date(raw_val)
    elif val_type == "amount":
        return format_amount(raw_val)
    return raw_val


def load_packet(packet_dir):
    data_by_doc = {}
    for fname in os.listdir(packet_dir):
        fpath = os.path.join(packet_dir, fname)
        if not os.path.isfile(fpath) or fname.startswith("."):
            continue
        doc_name, ext = os.path.splitext(fname)
        ext = ext.lower()
        if ext in (".csv", ".tsv", ".txt"):
            rows = []
            for enc in ("utf-8", "latin-1", "cp1252"):
                try:
                    with open(fpath, "r", encoding=enc) as f:
                        sample = f.read(2048)
                        f.seek(0)
                        delim = (
                            "\t"
                            if "\t" in sample
                            and sample.count("\t") > sample.count(",")
                            else ","
                        )
                        reader = csv.DictReader(f, delimiter=delim)
                        for r in reader:
                            clean_r = {
                                (k.strip() if k else ""): (
                                    v.strip() if v else ""
                                )
                                for k, v in r.items()
                            }
                            rows.append(clean_r)
                    break
                except UnicodeDecodeError:
                    continue
            data_by_doc[doc_name] = rows
    return data_by_doc


def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    packet_data = load_packet(packet_dir)

    # Build index for lca_disclosure by CASE_NUMBER
    doc_name = "lca_disclosure"
    lca_rows = packet_data.get(doc_name, [])
    records_by_entity = {}
    for r in lca_rows:
        entity_id = r.get("CASE_NUMBER", "").strip()
        if entity_id:
            records_by_entity.setdefault(entity_id, []).append(r)

    results = {}
    pairs = manifest.get("pairs", [])
    facts_spec = manifest.get("facts", {})

    for pair in pairs:
        if "::" in pair:
            rule_id, entity = pair.split("::", 1)
        else:
            rule_id, entity = pair, ""

        rule_facts = facts_spec.get(rule_id, [])
        pair_result = {}

        entity_records = records_by_entity.get(entity, [])

        for fact in rule_facts:
            config = FACT_CONFIG.get(fact)
            if not config:
                norm_fact = fact.strip().lower()
                config = FACT_CONFIG.get(norm_fact)

            if config:
                col_name, val_type = config
            else:
                col_name = fact.upper().replace(" ", "_")
                val_type = (
                    "date"
                    if "date" in fact.lower()
                    else "amount"
                    if ("wage" in fact.lower() or "pay" in fact.lower())
                    else "text"
                )

            extracted_values = []
            for record in entity_records:
                raw_val = record.get(col_name)
                formatted = format_value(raw_val, val_type)
                if formatted is not None and formatted != "":
                    extracted_values.append(formatted)

            unique_values = sorted(list(set(extracted_values)))

            if len(unique_values) == 0:
                pair_result[fact] = "ABSENT"
            elif len(unique_values) == 1:
                pair_result[fact] = [unique_values[0], doc_name]
            else:
                pair_result[fact] = "CONFLICT"

        results[pair] = pair_result

    print(json.dumps(results, indent=2))


if __name__ == "__main__":
    main()

